<?php
namespace ProjectPress\Admin\Manager\Projects;
use ProjectPress\Includes\Functions\Helpers\RequestHelper;
use ProjectPress\Includes\Project\Core\Project;
use ProjectPress\Includes\Project\Core\ProjectPermissions;
use ProjectPress\Includes\Project\ProjectManager as DomainProjectManager;
use ProjectPress\Includes\Project\Work\TaskRepository;
use ProjectPress\Includes\Project\Work\TaskService;
use WP_Error;
if(!defined('ABSPATH')){exit;}
final class Tasks{
 private DomainProjectManager $projects;private ProjectPermissions $permissions;private TaskRepository $repository;private TaskService $service;
 public function __construct(?DomainProjectManager $projects=null,?ProjectPermissions $permissions=null){$this->projects=$projects??DomainProjectManager::get_instance();$this->permissions=$permissions??new ProjectPermissions();$this->repository=new TaskRepository();$this->service=new TaskService($this->repository,$this->projects->repository(),$this->permissions);}
 public function render(Project $project):void{$tasks=$this->repository->for_project($project->get_id());$can_edit=$this->permissions->can_edit($project);?>
 <div class="row g-4"><div class="col-xl-8"><div class="card card-body"><div class="d-flex justify-content-between align-items-center mb-3"><h2 class="h4 mb-0"><?php esc_html_e('Tasks','projectpress');?></h2><?php if(!$can_edit):?><span class="badge text-bg-secondary"><?php esc_html_e('Read only','projectpress');?></span><?php endif;?></div>
 <?php if(empty($tasks)):?><p class="text-secondary mb-0"><?php esc_html_e('No tasks have been created for this project.','projectpress');?></p><?php endif;?>
 <?php foreach($tasks as $task):$assignee=$task->get_assignee_id()?get_user_by('id',$task->get_assignee_id()):false;?><div class="border rounded p-3 mb-3"><div class="d-flex flex-wrap justify-content-between gap-2"><div><strong><?php echo esc_html($task->get_title());?></strong><?php if(''!==$task->get_description()):?><div class="text-secondary small"><?php echo esc_html($task->get_description());?></div><?php endif;?></div><div><span class="badge text-bg-light"><?php echo esc_html($this->humanise($task->get_status()));?></span> <span class="badge text-bg-light"><?php echo esc_html($this->humanise($task->get_priority()));?></span></div></div><div class="small text-secondary mt-2"><?php echo esc_html($assignee?sprintf(__('Assigned to %s','projectpress'),$assignee->display_name):__('Unassigned','projectpress'));?><?php if($task->get_due_date()):?> · <?php echo esc_html(sprintf(__('Due %s','projectpress'),substr($task->get_due_date(),0,10)));?><?php endif;?></div>
 <?php if($can_edit):?><form class="mt-2" method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_task_delete"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project->get_id());?>"/><input type="hidden" name="task_id" value="<?php echo esc_attr((string)$task->get_id());?>"/><?php wp_nonce_field('projectpress_workspace_task_delete');?><button class="btn btn-sm btn-outline-danger" type="submit"><?php esc_html_e('Delete','projectpress');?></button></form><?php endif;?></div><?php endforeach;?></div></div>
 <div class="col-xl-4"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Create Task','projectpress');?></h2><?php if(!$can_edit):?><p class="text-secondary mb-0"><?php esc_html_e('You do not have permission to create tasks in this project.','projectpress');?></p><?php else:?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="projectpress_workspace_task_save"/><input type="hidden" name="project_id" value="<?php echo esc_attr((string)$project->get_id());?>"/><?php wp_nonce_field('projectpress_workspace_task_save');?><label class="form-label" for="task-title"><?php esc_html_e('Title','projectpress');?></label><input class="form-control" id="task-title" name="title" required/><label class="form-label mt-3" for="task-description"><?php esc_html_e('Description','projectpress');?></label><textarea class="form-control" id="task-description" name="description"></textarea><label class="form-label mt-3" for="task-status"><?php esc_html_e('Status','projectpress');?></label><select class="form-select" id="task-status" name="status"><?php foreach(TaskService::statuses() as $v):?><option value="<?php echo esc_attr($v);?>"><?php echo esc_html($this->humanise($v));?></option><?php endforeach;?></select><label class="form-label mt-3" for="task-priority"><?php esc_html_e('Priority','projectpress');?></label><select class="form-select" id="task-priority" name="priority"><?php foreach(TaskService::priorities() as $v):?><option value="<?php echo esc_attr($v);?>"><?php echo esc_html($this->humanise($v));?></option><?php endforeach;?></select><label class="form-label mt-3" for="task-assignee"><?php esc_html_e('Assignee User ID','projectpress');?></label><input class="form-control" type="number" min="1" id="task-assignee" name="assignee_id"/><label class="form-label mt-3" for="task-due"><?php esc_html_e('Due date','projectpress');?></label><input class="form-control" type="date" id="task-due" name="due_date"/><button class="btn btn-primary mt-3" type="submit"><?php esc_html_e('Create Task','projectpress');?></button></form><?php endif;?></div></div></div><?php }
 public function handle_save():void{check_admin_referer('projectpress_workspace_task_save');$project_id=RequestHelper::integer($_POST,'project_id',0);$result=$this->service->create($project_id,array('title'=>RequestHelper::text($_POST,'title',''),'description'=>RequestHelper::text($_POST,'description',''),'status'=>RequestHelper::key($_POST,'status','todo'),'priority'=>RequestHelper::key($_POST,'priority','normal'),'assignee_id'=>RequestHelper::integer($_POST,'assignee_id',0),'due_date'=>RequestHelper::text($_POST,'due_date','')));$this->redirect($project_id,$result);}
 public function handle_delete():void{check_admin_referer('projectpress_workspace_task_delete');$project_id=RequestHelper::integer($_POST,'project_id',0);$task=$this->repository->find(RequestHelper::integer($_POST,'task_id',0));if(!$task||$task->get_project_id()!==$project_id){$this->redirect($project_id,new WP_Error('projectpress_task_not_found',__('Task not found.','projectpress')));}$this->redirect($project_id,$this->service->delete($task));}
 private function redirect(int $project_id,$result):void{$url=add_query_arg(array('page'=>'projectpress','group'=>'projects','project_id'=>absint($project_id),'tab'=>'tasks'),admin_url('admin.php'));$url=is_wp_error($result)?add_query_arg('project_error',rawurlencode($result->get_error_message()),$url):add_query_arg('project_saved','1',$url);wp_safe_redirect($url);exit;}
 private function humanise(string $v):string{return ucwords(str_replace('_',' ',$v));}
}
